<span class="line"><span style="color:#E06C75;">            rightSum</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> Math</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">Max</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">rightSum</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">sum</span><span style="color:#ABB2BF;">);</span></span>
